import {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import { usePromiseResult } from '@onekeyhq/kit/src/hooks/usePromiseResult';
import { formatDate } from '@onekeyhq/shared/src/utils/dateUtils';
import networkUtils from '@onekeyhq/shared/src/utils/networkUtils';
import type { ISignatureItemQueryParams } from '@onekeyhq/shared/types/signatureRecord';

import { SignatureContext } from './Context';

export const groupBy = <T extends { createdAt: number }>(items: T[]) => {
  const resp = items.reduce(
    (acc, item) => {
      const title = formatDate(new Date(item.createdAt), {
        hideTimeForever: true,
      });
      if (!acc[title]) {
        acc[title] = [];
      }
      acc[title].push(item);
      return acc;
    },
    {} as Record<string, T[]>,
  );
  return Object.entries(resp).map(([title, data]) => ({
    title,
    data,
  })) as { title: string; data: T[] }[];
};

export const useGetSignatureSections = <T extends { createdAt: number }>(
  method: (params: ISignatureItemQueryParams) => Promise<T[]>,
) => {
  const ref = useRef<T[]>([]);
  const methodRef = useRef(method);
  const hasLoadedFirstPageRef = useRef(false);
  const resetGenRef = useRef(0);
  const { networkId, searchContent: address } = useContext(SignatureContext);
  const [query, setQuery] = useState<{
    networkId?: string;
    address?: string;
    offset: number;
    limit: number;
  }>({
    networkId,
    address,
    offset: 0,
    limit: 10,
  });
  const offset =
    query.networkId === networkId && query.address === address
      ? query.offset
      : 0;

  // Reset accumulated data and pagination when filters change
  useEffect(() => {
    ref.current = [];
    hasLoadedFirstPageRef.current = false;
    resetGenRef.current += 1;
    setQuery({ networkId, address, offset: 0, limit: 10 });
  }, [networkId, address]);

  const { result, isLoading, run } = usePromiseResult(
    async () => {
      const gen = resetGenRef.current;
      let resp: T[];
      try {
        resp = await methodRef.current({
          networkId,
          address,
          offset,
          limit: query.limit,
        });
      } catch (error) {
        if (resetGenRef.current !== gen || offset !== 0) {
          throw error;
        }
        return {
          sections: [],
          ending: true,
          networkId,
          address,
          hasError: true,
        };
      }
      // Skip stale results from before a filter reset
      if (resetGenRef.current !== gen) {
        return {
          sections: [],
          ending: false,
          networkId,
          address,
          hasError: false,
        };
      }
      const isSearch = !networkUtils.isAllNetwork({ networkId }) || address;
      if (!isSearch) {
        if (offset === 0) {
          ref.current = [...resp];
        } else {
          ref.current.splice(offset, query.limit, ...resp);
        }
      }
      hasLoadedFirstPageRef.current = true;
      return {
        sections: groupBy(isSearch ? resp : ref.current),
        ending: resp.length < query.limit,
        networkId,
        address,
        hasError: false,
      };
    },
    [networkId, query.limit, offset, address],
    {
      initResult: {
        sections: [],
        ending: false,
        networkId: '',
        address: '',
        hasError: false,
      },
      watchLoading: true,
    },
  );

  const isCurrentFilter =
    result.networkId === networkId && result.address === address;
  const sections = useMemo(
    () => (isCurrentFilter ? result.sections : []),
    [isCurrentFilter, result.sections],
  );
  const ending = isCurrentFilter ? result.ending : false;
  const isSectionsLoading = Boolean(isLoading || !isCurrentFilter);
  const hasError = isCurrentFilter && result.hasError;

  const onRetry = useCallback(() => {
    void run();
  }, [run]);

  const onEndReached = useCallback(() => {
    if (ending || !isCurrentFilter || !hasLoadedFirstPageRef.current) {
      return;
    }
    setQuery((prev) => ({
      ...prev,
      networkId,
      address,
      offset:
        (prev.networkId === networkId && prev.address === address
          ? prev.offset
          : 0) + prev.limit,
    }));
  }, [ending, isCurrentFilter, networkId, address]);

  return useMemo(
    () => ({
      sections,
      isLoading: isSectionsLoading,
      hasError,
      onRetry,
      onEndReached,
    }),
    [sections, isSectionsLoading, hasError, onRetry, onEndReached],
  );
};
